import reviewedLines from '../data/openingReviewedLines.js'

// Individually written notes for the ninth and thirteenth move pairs.
// The reviewed full lines are frozen separately. A changed line must be reviewed
// again before its notes can be reused; do not rebuild that snapshot in a build.
const entry=(id,ninth,thirteenth)=>[id,{line:reviewedLines[id],notes:{16:ninth,24:thirteenth}}]

export default Object.fromEntries([
  entry('french:classical',
    'Dd2 collega le torri e prepara l’arrocco lungo. Con ...Cc6 il Nero aggiunge pressione sia a d4 sia a e5: il centro bianco dà spazio, ma richiede sostegni prima di iniziare l’attacco sul fianco.',
    'Cd6 porta il cavallo nel campo nero e attacca b7 e f7. ...Tab8 attiva una torre sulla colonna b: il Bianco deve valutare il controgioco sul lato di donna, dove si trova anche il proprio re in c1.'),
  entry('french:rubinstein',
    'Te1 usa la colonna e, semiaperta per il Bianco dopo il cambio del pedone iniziale. Il Nero arrocca e collega le torri: la pressione su e6 va confrontata con la possibilità di difenderlo e completare lo sviluppo.',
    'Dxf3 riprende l’alfiere, ma ...Cxd3 elimina quello bianco in d3. Prima di scegliere una ricattura bisogna osservare l’intera sequenza dei cambi: la struttura centrale resta, mentre cambia il confronto fra pezzi minori.'),
  entry('french:steinitz',
    'Cf3 sostiene d4 ed e5; ...f6 attacca proprio il pedone e5. Il Nero cerca di aprire il centro mentre il re bianco è ancora in e1: una minaccia al pedone e6 non deve far dimenticare il costo in tempi di sviluppo.',
    'Re2 risponde allo scacco dell’alfiere f2, rinunciando all’arrocco. ...a5 guadagna spazio sul lato di donna: il Bianco ha raccolto pedoni, ma deve ora coordinare i pezzi attorno a un re esposto.'),
  entry('french:maccutcheon',
    'Ad3 sviluppa un pezzo contro il cavallo e4; ...Cxd2 cambia quel cavallo per l’altro alfiere. Il Nero modifica il confronto fra pezzi e la ricattura può coinvolgere il re bianco: attività e sicurezza vanno valutate insieme.',
    'Df4 mantiene pressione su f7 e h6. Con ...Dxc5 il Nero recupera il pedone e centralizza la donna: l’attacco sul lato di re deve fare i conti con una risposta concreta al centro e con il re bianco in d2.'),
  entry('french:tarrasch-closed',
    'exf6 e ...Cxf6 eliminano la punta della catena bianca e attivano un cavallo nero. La posizione non è più il centro bloccato iniziale: la colonna e e la pressione sul pedone d4 diventano riferimenti per il seguito.',
    'Cxf4 conclude il cambio degli alfieri, ma ...Cg4 porta pressione su f2 e h2. Il Bianco deve distinguere l’attività del cavallo centrale dalle minacce al proprio re: il controllo del centro non sostituisce la difesa dei bersagli.'),
  entry('french:winawer-poisoned',
    'Dxh7 raccoglie un secondo pedone sul lato di re; ...cxd4 attacca c3 e cambia il centro. È il tema del pedone avvelenato: il materiale preso dalla donna lascia agli altri pezzi il compito di reggere l’iniziativa avversaria.',
    'Dxc3 riporta la donna verso il centro e recupera il pedone avanzato. Il Nero arrocca lungo: ora la colonna d e lo sviluppo dei pezzi contano più del semplice bilancio dei pedoni catturati sul lato di re.'),
  entry('sicilian:sveshnikov',
    'Cd5 occupa la casa davanti al pedone d6 e attacca il cavallo f6. ...Ae7 prepara l’arrocco: la debolezza di d5 offre un punto di appoggio, ma il Nero conserva spazio sul lato di donna e possibilità di cambiare il cavallo invasore.',
    'a4 mette in discussione la catena nera sul lato di donna. ...bxa4 apre la colonna a: il Bianco può attivare la torre, mentre il Nero deve valutare le case lasciate dai pedoni, non soltanto lo spazio guadagnato in apertura.'),
  entry('sicilian:taimanov',
    'Ae2 prepara l’arrocco bianco, mentre il Nero mette al sicuro il re. Il centro con c4 ed e4 limita alcune spinte nere, ma il cavallo bianco in a3 dovrà trovare un percorso utile: spazio e sviluppo non coincidono.',
    'Tad1 porta una torre sulla colonna del pedone d6. ...Dc7 coordina la difesa senza fissare per sempre il centro: il Nero cercherà il momento per ...d5, mentre il Bianco deve mantenere i pezzi pronti all’apertura delle linee.'),
  entry('sicilian:kan',
    'Il Bianco arrocca; ...d6 sostiene e5 e lascia al Nero un centro compatto. Con il pedone bianco in c4 e il cavallo nero in e5, il gioco dipende dai cambi dei pezzi che controllano le case centrali.',
    'Axf6 e ...gxf6 eliminano un difensore e doppiano i pedoni neri sulla colonna f. Il Nero ottiene però una colonna g semiaperta: giudicare la struttura senza considerare dove si trova il re porterebbe a una valutazione incompleta.'),
  entry('sicilian:accelerated-dragon',
    'Il Bianco arrocca e il Nero sviluppa l’alfiere in d7. La coppia c4-e4 limita la rottura ...d5: per il Nero il compito è coordinare i pezzi contro quel controllo, senza forzare una spinta centrale prima che sia preparata.',
    'b3 sostiene c4; ...Cd7 toglie il cavallo dalla diagonale dell’alfiere d4 e prepara un diverso accesso al centro. Nel Maroczy conservare il controllo non significa poter evitare ogni cambio: conta quali pezzi restano a difendere le case.'),
  entry('sicilian:rossolimo',
    'h3 controlla g4, mentre ...Ad7 sviluppa l’ultimo alfiere nero. Dopo ...d5 ed e5 il centro ha già cambiato forma: il Bianco deve valutare se cambiare in c6, anziché proseguire un piano della Siciliana aperta che qui non è stato giocato.',
    'Ca3 cerca un percorso verso le case centrali; ...Dd7 collega i pezzi e guarda h3 lungo la diagonale. Il cavallo sul bordo va giudicato per le case che potrà raggiungere, mentre il Nero cerca attività senza indebolire il proprio re.'),
  entry('sicilian:closed',
    'Ae3 sviluppa contro c5, ma ...Cd4 porta il cavallo verso f3 e c2. Anche senza il cambio iniziale dei pedoni d e c la lotta centrale è concreta: il Bianco deve valutare l’intrusione prima di spingere ancora sul lato di re.',
    'Axf3 riprende il cavallo; ...dxe5 cambia il centro e attacca f4. La ricattura successiva potrà aprire diagonali per entrambi gli alfieri: una posizione nata chiusa può richiedere calcolo immediato quando le catene si separano.'),
  entry('spanish:marshall',
    'exd5 e ...Cxd5 aprono il centro. Il Nero offre il pedone e5 per attivare i pezzi contro il re bianco: prima di accettare altro materiale bisogna confrontare i tempi di sviluppo e le linee degli alfieri.',
    'Te1 sottrae la torre alla pressione dell’alfiere d6; ...Dh4 porta donna e alfiere verso h2. Il pedone in più non risolve la difesa: il Bianco deve cercare una risposta che tenga conto delle minacce al re.'),
  entry('spanish:open',
    'Cxc6 attacca la donna d8, ma ...Axh2+ introduce uno scacco intermedio. Una minaccia alla donna non obbliga a ritirarla subito quando esiste una risposta forzante contro il re: l’ordine delle mosse è decisivo.',
    'Cxd8+ conclude una sequenza di catture delle donne e dà scacco. ...b5 lo interrompe sulla diagonale dell’alfiere a4 e attacca quell’alfiere: la semplificazione non elimina le mosse intermedie né rende automatiche le ricatture.'),
  entry('spanish:schliemann',
    'f4 attacca la donna g5, che risponde catturando in f4. Il Nero mantiene attività, ma la donna può diventare un bersaglio: in questo centro aperto bisogna contare anche i tempi guadagnati con gli scacchi, non soltanto i pedoni.',
    'Ac4 sottrae l’alfiere alla pressione del pedone c6; ...Ae6 lo attacca di nuovo. Il Nero sviluppa guadagnando tempo, mentre il Bianco deve coordinare il re e gli altri pezzi prima di cercare un nuovo attacco.'),
  entry('spanish:steinitz',
    'dxe5 e ...dxe5 aprono la colonna d e rendono possibile il cambio delle donne. Il Bianco rinuncia alla tensione centrale per cercare attività: dopo le semplificazioni conteranno l’ingresso dei pezzi e la difesa dei pedoni rimasti.',
    'f3 sostiene e4 e controlla g4; ...b5 guadagna spazio sul lato di donna. Senza donne il re è meno esposto, ma il Nero può ancora creare controgioco: il Bianco deve coordinare il centro senza ignorare l’espansione avversaria.'),
  entry('italian:hungarian',
    'Il Bianco arrocca e il Nero cattura in e5, attaccando d4. La scelta prudente iniziale ...Ae7 ha portato a un centro aperto: completare la sicurezza del re permette di affrontare i cambi con le torri pronte a entrare in gioco.',
    'f3 attacca il cavallo e4, che si sposta in c5. Il Bianco guadagna tempo sul pezzo, ma modifica le case attorno al proprio re: la successiva attività deve compensare questo impegno di pedoni.'),
  entry('italian:fried-liver',
    'Cf3 si sottrae a ...h6, ma ...e4 attacca di nuovo il cavallo. Il Nero usa il centro per guadagnare tempi: l’attacco iniziale a f7 non autorizza il Bianco a ignorare i pedoni avversari e lo sviluppo rimasto indietro.',
    'b3 prepara lo sviluppo dell’alfiere c1; il Nero arrocca e collega le torri. L’iniziativa iniziale si è trasformata in un problema di coordinazione: il Bianco deve mettere in gioco l’alfiere e valutare le colonne aperte.'),
  entry('italian:scotch-gambit',
    'Cxe4 elimina il cavallo avanzato; ...Ae6 sviluppa e controlla d5. Il Bianco ha usato la colonna e per accelerare il gioco, ma ogni nuovo cambio va confrontato con la possibilità del Nero di completare lo sviluppo e arroccare lungo.',
    'Ag5 mette pressione alla torre d8; ...Tdf8 la sposta sulla colonna f e attacca il cavallo f3. Il Nero risponde alla minaccia creando attività altrove: il Bianco deve controllare i bersagli prima di continuare a raccogliere pedoni.'),
  entry('italian:giuoco-center',
    'd5 attacca il cavallo c6 e guadagna spazio, mentre ...Af6 sottrae l’alfiere alla pressione. Il Bianco cerca iniziativa dopo i cambi centrali: prima di riprendere il cavallo e4 bisogna verificare le linee lasciate aperte dai pezzi.',
    'g5 attacca l’alfiere f6, che raggiunge e5 e guarda h2. Inseguire un pezzo può migliorargli la diagonale: il Bianco deve confrontare lo spazio sul fianco con la sicurezza del proprio re e con i pezzi che possono cambiare l’alfiere.'),
  entry('scandinavian:qd6',
    'f3 sostiene e4 e impedisce alcuni ingressi in g4; ...Cbd7 sviluppa il cavallo con controllo di e5 e c5. La donna nera in b4 ha già richiesto tempi: il Bianco può sfruttarli se lo sviluppo resta collegato al centro.',
    'De1 sposta la donna dalla colonna d; ...Ab4 aumenta la pressione sul cavallo c3. Con il re bianco in c1 questo pezzo partecipa alla difesa: un cambio in c3 può aprire linee proprio sul lato dell’arrocco.'),
  entry('scandinavian:qd8',
    'g5 attacca il cavallo f6, che raggiunge d5 e mette pressione a c3. Il Bianco guadagna spazio inseguendo un pezzo, ma gli concede una casa centrale: occorre confrontare la catena di pedoni con l’attività del cavallo.',
    'b4 attacca l’alfiere a5; ...Ab6 conserva la diagonale verso d4. Il Bianco ha spinto su entrambi i fianchi con il re ancora al centro: prima di un nuovo guadagno di spazio deve valutare sviluppo e aperture delle linee.'),
  entry('scandinavian:portuguese',
    'bxa6 conserva un pedone avanzato, ma ...e6 libera l’alfiere f8 e sostiene il cavallo d5. Il Nero ha investito materiale nello sviluppo: il Bianco deve capire quanto costa difendere a6 rispetto a mettere al sicuro il re.',
    'Cxc3 riprende il cavallo e il Nero arrocca. La fase dei pedoni offerti lascia spazio al confronto fra pezzi: il Bianco deve coordinare la propria maggioranza, mentre la torre nera già attiva in a6 cerca nuove colonne.'),
  entry('scandinavian:icelandic',
    'Ae3 sviluppa, ma ...Axc3+ impone prima una risposta al re. Il Nero usa gli scacchi per gestire i cambi: non basta attaccare un pezzo se l’avversario può modificare l’ordine delle ricatture con una mossa forzante.',
    'Rg1 migliora la posizione del re bianco, mentre il Nero arrocca lungo. I pedoni c doppiati e le colonne aperte rendono importante l’attività delle torri: la compensazione del gambetto va valutata nella posizione attuale, dopo i cambi.'),
  entry('pirc:classical',
    'd5 guadagna spazio e attacca il cavallo c6, che si ritira in e7. Il centro chiuso assegna tempi diversi ai due lati: il Bianco può preparare f4, mentre il Nero deve cercare controgioco sui fianchi o contro la catena.',
    'Ch2 e ...Ce8 riorganizzano entrambi i cavalli. Non sono mosse di sviluppo iniziale: liberano percorsi e preparano spinte di pedone. Prima di giudicare un arretramento occorre vedere quale rottura rende possibile.'),
  entry('pirc:150-attack',
    'Cge2 sviluppa senza occupare f3; ...Cbd7 aggiunge controllo a e5 e c5. Le donne sono ancora attive e i re al centro: le spinte sui fianchi richiedono di scegliere quando completare la sicurezza del re.',
    'Ah3 sviluppa sulla diagonale lasciata libera da g4; ...cxd4 cambia il centro e attacca c3. L’attacco sul fianco non procede da solo: la pressione sul cavallo e l’apertura delle colonne possono diventare più urgenti.'),
  entry('pirc:modern',
    'Il Bianco arrocca, mentre ...Da5 attacca l’alfiere g5 lungo la diagonale. La donna nera ha preso b2 ma resta esposta ai tempi di sviluppo: il Bianco deve conservare l’iniziativa senza dimenticare il pezzo attaccato.',
    'dxc5 e ...Dxc5 aprono il centro. Dalla nuova casa la donna nera attacca sia l’alfiere c4 sia la torre e3: prima di cercare un’invasione sul lato di re il Bianco deve confrontare questi due bersagli.'),
  entry('pirc:fianchetto',
    'a5 limita b6; ...Dc7 coordina il lato di donna e guarda il pedone avanzato. L’alfiere bianco in g2 non implica un gioco passivo: lo spazio sul fianco va sostenuto senza allentare la difesa del centro.',
    'b5 attacca c6; ...Ab7 sviluppa l’alfiere lungo la grande diagonale. I cambi già avvenuti sulla colonna a offrono ingressi alle torri: il Bianco deve valutare l’apertura del fianco insieme alla pressione sull’arrocco corto.'),
  entry('alekhine:exchange',
    'h3 controlla g4; ...Cc6 sviluppa contro d4. Dopo il cambio in d6 il centro non è più la catena avanzata iniziale: il Bianco deve sostenere i pedoni centrali senza concedere al Nero tempi per attaccarli.',
    'dxe5 e ...dxe5 aprono la colonna d e lasciano al Nero un pedone in e5. La tensione è risolta, ma cambiano le case utili per i pezzi: l’attività sulla colonna può diventare più importante del vantaggio di spazio iniziale.'),
  entry('alekhine:modern',
    'Cc3 rafforza il controllo di d5 ed e4, mentre il Nero arrocca. Il Bianco ha smesso di inseguire i cavalli con nuovi pedoni: completare lo sviluppo prepara a reagire alla futura rottura centrale.',
    'b4 sostiene c5; ...a6 controlla b5 e prepara controgioco sul lato di donna. Il Bianco ha spazio, ma anche pedoni doppiati sulla colonna f: scegliere il piano richiede di confrontare l’espansione sul fianco con la sicurezza del re.'),
  entry('alekhine:two-pawns',
    'Db3 coordina donna e alfiere d5 verso f7; ...Axc5 recupera un pedone e punta a f2. Entrambi i lati creano minacce: prima di catturare ancora bisogna controllare gli scacchi disponibili e la posizione dei re.',
    'Il Bianco arrocca; ...g6 attacca l’alfiere h5. L’attacco iniziale ha privato il re nero dell’arrocco, ma non rende automatico il seguito: l’alfiere attaccato e lo sviluppo del lato di donna richiedono ancora attenzione.'),
  entry('alekhine:scandinavian',
    'd4 occupa il centro, mentre ...b6 prepara l’alfiere in b7. La ricattura precedente con il pedone b ha lasciato due pedoni bianchi sulla colonna c: la loro struttura va confrontata con le linee aperte per gli alfieri.',
    'dxc5 attacca b6; ...Dc7 mette pressione al pedone c5 e guarda h2. Il Nero può recuperare materiale attraverso l’attività dei pezzi: il Bianco deve valutare se difendere il pedone avanzato aiuta davvero il proprio sviluppo.'),
  entry('petrov:cochrane',
    'Ad3 sviluppa verso il re nero; ...d5 attacca la donna e4 e contesta il centro. Il cavallo sacrificato in f7 non si recupera con un piano automatico: il Bianco deve mantenere l’iniziativa attraverso tempi e minacce concrete.',
    'c3 sostiene d4; ...c5 lo attacca di nuovo. Il Nero cerca di rompere il centro che sostiene l’attacco bianco: chi ha sacrificato materiale deve verificare se i cambi aprono linee utili oppure favoriscono la difesa.'),
  entry('petrov:three-knights',
    'a4 sostiene l’alfiere b5, ma ...Cxb5 sceglie comunque il cambio del cavallo per l’alfiere. La ricattura modifica il lato di donna: la struttura che ne nasce conta più dell’idea astratta di conservare sempre la coppia degli alfieri.',
    'Af4 sviluppa con controllo di e5 e d6; ...d6 sostiene il centro e propone un nuovo confronto fra pedoni. Il Bianco deve coordinare i pezzi dietro la catena avanzata: il centro simmetrico dell’apertura è già stato trasformato.'),
  entry('petrov:modern-nc3',
    'Il Bianco arrocca lungo; ...c6 sostiene una futura spinta in d5. I pedoni c doppiati offrono al Bianco la colonna d semiaperta: l’attività delle torri deve accompagnare la protezione del re in c1.',
    'Ad4 attacca il cavallo f6; ...h6 crea una casa in h7 e controlla g5. Il Nero non è costretto a spostare subito il cavallo se il cambio può essere gestito: il Bianco deve calcolare le ricatture prima di giudicare la minaccia.'),
  entry('petrov:italian',
    'Dh4 guarda h7, mentre ...Cc6 sviluppa con controllo di d4 ed e5. La donna bianca attiva può sostenere un attacco, ma il Nero guadagna coordinazione: servono pezzi pronti a partecipare, non soltanto una minaccia di donna.',
    'Dxf6 e ...gxf6 cambiano le donne e doppiano i pedoni neri sulla colonna f. Il gioco passa dalla pressione sul re al confronto fra struttura e attività: anche il Bianco deve ancora decidere come riprendere l’alfiere in f3.'),
  entry('scotch:mieses',
    'b3 sostiene c4 e prepara l’alfiere b2; il Nero arrocca lungo. La catena bianca dà spazio, ma gli alfieri neri hanno diagonali attive: lo sviluppo deve accompagnare la difesa del centro prima di iniziare un attacco.',
    'f4 attacca la donna g5 e sostiene e5; ...Dg6 conserva pressione lungo la diagonale verso e4. Guadagnare un tempo sulla donna è utile se lascia i pezzi coordinati, senza trasformare il centro avanzato in un bersaglio.'),
  entry('scotch:goering',
    'Te1 prepara la pressione dietro il pedone e4 e il Nero arrocca. Il Bianco ha investito un pedone nello sviluppo: deve creare minacce prima che l’avversario completi la coordinazione, senza assumere che il gambetto garantisca un attacco.',
    'Dd2 collega i pezzi; ...Ad7 riposiziona l’alfiere. Le torri sulla colonna e e il pedone bianco in e4 rendono possibile una rottura centrale, ma prima occorre verificare quali catture sostengono i pezzi rimasti.'),
  entry('scotch:steinitz',
    'Cxc7+ dà scacco e attacca la torre a8. ...Rd8 risponde allo scacco senza risolvere quel bersaglio: prima di prendere la torre il Bianco deve valutare se il cavallo potrà rientrare e quanto tempo guadagnano i pezzi neri.',
    'b4 attacca l’alfiere a5; ...Cd4 crea pressione su e2 e c2. Il Nero sceglie attività centrale invece di rispondere subito all’attacco sull’alfiere: i guadagni materiali vanno confrontati con gli scacchi e con il re bianco ancora in e1.'),
  entry('vienna:fianchetto',
    'dxc6 e ...Cxc6 risolvono la tensione e riattivano il cavallo nero al centro. Il fianchetto bianco controlla una lunga diagonale, ma il suo valore dipende dai pedoni che la aprono o la chiudono dopo i cambi.',
    'Txf6 sacrifica una torre per il cavallo; ...gxf6 accetta e modifica la copertura del re nero. Il Bianco cerca attività sulle case centrali e contro il re: la struttura danneggiata da sola non dimostra che il sacrificio sia sufficiente.'),
  entry('vienna:bishop',
    'Cxc7+ attacca il re e la torre a8; ...Rd8 risponde allo scacco. Il Bianco può guadagnare materiale, ma deve includere nel calcolo il ritorno del cavallo e lo sviluppo degli altri pezzi ancora sulla prima traversa.',
    'Df3 centralizza la donna; ...Cd4 attacca insieme donna f3 e alfiere b3, oltre a c2. Questa minaccia concreta ha precedenza sui piani generali: conservare il materiale ottenuto richiede ora di confrontare più bersagli.'),
  entry('vienna:falkbeer',
    'a4 sostiene l’alfiere b5, ma il Nero sceglie ...Cxb5 e consente la ricattura del pedone a. La posizione è entrata in una struttura dei Quattro Cavalli: il nome dell’apertura non deve nascondere i cambi effettivi sul lato di donna.',
    'Af4 sviluppa con controllo di e5 e d6; ...d6 sostiene il centro e propone un nuovo confronto fra pedoni. Dopo la spinta nera ...e4 occorre aggiornare i piani: il centro iniziale simmetrico non esiste più.'),
  entry('kings-gambit:fischer',
    'Cg1 si ritira dall’attacco del pedone g4; ...f3 attacca g2 e mantiene un pedone dentro il campo bianco. Il Nero usa lo spazio per ostacolare lo sviluppo: il Bianco deve liberare i pezzi prima di cercare un attacco al re.',
    'Df1 si sottrae alla pressione del cavallo e5; ...Cf6 sviluppa contro e4. I sacrifici iniziali hanno prodotto un confronto di tempi: la donna bianca deve trovare sicurezza senza lasciare il centro privo di sostegno.'),
  entry('kings-gambit:bishops',
    'dxc3 riprende l’alfiere e rende semiaperta la colonna d per il Bianco; ...g4 guadagna spazio sul lato di re. La struttura bianca è cambiata e il re ha perso l’arrocco: lo sviluppo deve sfruttare le nuove linee per compensare l’esposizione.',
    'h3 mette pressione al pedone g4; ...Df6 attacca l’alfiere f4 e il pedone c3. Il Nero collega la donna a due bersagli: prima di continuare le spinte di pedone, il Bianco deve valutare quale minaccia richiede una risposta.'),
  entry('kings-gambit:falkbeer',
    'Cfd2 attacca il cavallo e4; ...f5 lo sostiene. Il Nero risponde al gambetto costruendo un centro attivo: il Bianco deve verificare i cambi sul punto e4 mentre il proprio re, in d1, può essere coinvolto dagli scacchi.',
    'b3 attacca la donna a4 e interrompe lo scacco sulla diagonale a4-d1; ...Da5 conserva attività verso c3. Una risposta allo scacco può guadagnare tempo, ma occorre verificare quali nuove linee lascia aperte attorno al re.'),
  entry('kings-gambit:declined-bc5',
    'Db3 sostiene l’alfiere c4; ...Df6 attiva la donna nera. Il Nero ha rifiutato il pedone iniziale: il Bianco deve costruire l’iniziativa con lo sviluppo, senza contare su tempi regalati dalla cattura.',
    'Ce6 attacca la donna f8; ...Axe6 elimina il cavallo. Il Bianco deve calcolare la ricattura dell’alfiere c4 e confrontare attività e struttura: una minaccia alla donna può essere risolta anche cambiando il pezzo che la crea.'),
  entry('philidor:hanham',
    'exd5 prende al centro, ma ...exf4 cattura altrove invece di ricatturare subito. Il Nero cambia la forma del centro e apre linee: prima di conservare il pedone d5 il Bianco deve valutare i pezzi che potranno attaccarlo.',
    'Axf4 recupera il pedone e attacca il cavallo h6; ...Cf5 lo rende attivo contro d4. Il Bianco ha recuperato materiale, ma il Nero guadagna un bersaglio centrale: lo sviluppo deve sostenere il pedone oltre a cercare iniziativa.'),
  entry('philidor:lion',
    'Cxd4 ricattura e centralizza il cavallo; ...Te8 porta la torre sulla colonna del pedone e4. La struttura nera compatta non esclude attività: il Bianco deve mantenere i sostegni del centro mentre completa la coordinazione.',
    'De3 si sottrae al cavallo h5; ...d5 attacca e4 e apre il confronto centrale. Il Nero ha preparato la rottura con i pezzi: il Bianco deve calcolare le catture e le possibili linee verso la donna, anziché continuare una manovra sul fianco.'),
  entry('philidor:countergambit',
    'Cxh8 prende la torre, mentre ...Axe6 recupera il pedone avanzato e sviluppa l’alfiere. Il cavallo bianco è lontano dal centro: il vantaggio materiale deve essere confrontato con il tempo necessario per rimetterlo in gioco.',
    'De2 sviluppa la donna e guarda e4; ...Rb7 allontana il re dalla colonna c dopo il cambio in c6. Il Nero cerca sicurezza per sostenere l’attività dei pezzi, mentre il Bianco deve completare lo sviluppo prima di raccogliere altro materiale.'),
  entry('queens-gambit:tarrasch',
    'Ag5 attacca il cavallo f6; ...cxd4 cambia al centro e attacca c3. Il Nero risponde alla pressione sui pezzi modificando i pedoni: il Bianco deve calcolare la ricattura prima di decidere se conservare l’inchiodatura.',
    'Cxe6 e ...fxe6 cambiano un cavallo per l’alfiere e portano un pedone nero in e6. Il pedone d5 non è più isolato: un giudizio valido sulla struttura iniziale della Tarrasch deve essere aggiornato dopo questa ricattura.'),
  entry('queens-gambit:chigorin',
    'Cxd4 recupera il pedone e attacca c6; il Nero arrocca. Lo sviluppo rapido ha consentito al Nero di cambiare il centro, ma ha anche ceduto un alfiere: il Bianco deve coordinare la coppia degli alfieri senza esporre il proprio re.',
    'Cxc6 e ...Axc6 eliminano i due cavalli coinvolti nel centro. L’alfiere nero in c6 mette pressione a f3: dopo i cambi non basta contare i pezzi, occorre vedere quali diagonali sono diventate attive.'),
  entry('queens-gambit:albin',
    'Axb4 e ...Dxb4+ cambiano gli alfieri con scacco. Il Nero usa l’attività della donna per mantenere tempi, mentre il Bianco deve rispondere al re prima di occuparsi del pedone avanzato d4.',
    'g3 prepara lo sviluppo dell’alfiere; ...Cg6 attacca e5. Le donne sono state cambiate, ma il pedone nero d4 continua a limitare il Bianco: completare lo sviluppo e difendere il pedone in più richiedono scelte coordinate.'),
  entry('queens-gambit:slav-chebanenko',
    'e3 sostiene d4; ...Ad6 sviluppa verso h2. Il pedone a5 limita il lato di donna nero, ma costa tempi di sviluppo: il Bianco deve completare la sicurezza del re prima di sfruttare lo spazio guadagnato.',
    'b4 sostiene a5 e prepara attività sul fianco; ...dxc4 risolve la tensione centrale. La ricattura con l’alfiere potrà attivarlo, ma il Nero cercherà a sua volta una rottura centrale: l’espansione non va separata dal centro.'),
  entry('london:early-c5',
    'Ce3 si ritira dall’attacco della donna a5; ...e5 attacca l’alfiere f4. Il Nero guadagna tempi con i pedoni centrali: dopo aver scelto e4, il Bianco non può trattare questa posizione come un Londra dal centro sempre stabile.',
    'Ac4 sviluppa verso f7; ...Ch7 allontana il cavallo dalla diagonale dell’alfiere h4. Il Nero prepara una diversa coordinazione, mentre il Bianco deve completare la sicurezza del re e controllare le spinte sul lato di re.'),
  entry('london:jobava',
    'Ad3 punta a h7; ...c5 attacca d4. Il Nero contrasta il centro invece di difendersi soltanto sul lato di re: il cavallo bianco in a3 deve rientrare nel gioco prima che le linee centrali si aprano.',
    'Df3 aumenta la pressione su d5, ma ...Cxe5 elimina il cavallo e attacca la donna. La ricattura centrale cambia l’ordine dei piani: prima di minacciare il re bisogna risolvere il confronto sul punto e5.'),
  entry('london:queen-pressure',
    'g4 attacca l’alfiere f5, che si ritira in g6. La donna nera ha già costretto una torre bianca in b1: le spinte sul lato di re devono essere valutate insieme ai tempi ancora necessari per completare lo sviluppo.',
    'Af3 attacca l’alfiere h5; ...Axf3 accetta il cambio e guarda la donna d1. Eliminare un alfiere attivo può essere utile, ma la ricattura deve conservare la coordinazione dei cavalli e del centro, non soltanto recuperare il pezzo.'),
  entry('kings-indian:panno',
    'h4 e ...h5 fissano il primo contatto sul lato di re. Il Nero ha già preparato ...b5 con ...a6 e ...Tb8: il Bianco deve scegliere la collocazione del re considerando il controgioco sull’altro fianco.',
    'Df4 attacca il cavallo f6 e il pedone d6; ...Cxc4 prende sul lato di donna e attacca b2. I re sono su lati opposti: prima di continuare l’attacco, entrambi devono confrontare la rapidità delle minacce avversarie.'),
  entry('kings-indian:fianchetto-panno',
    'Cd2 sostiene e4 e c4; ...c5 mette pressione a d4 e controlla b4. Il Nero attacca la catena bianca dalla base, mentre il Bianco deve coordinare i pezzi dietro il pedone d5 senza bloccare il proprio sviluppo.',
    'b4 attacca c5; ...cxb4 crea un pedone che attacca sia a3 sia il cavallo c3. Il cambio sul fianco può aprire la colonna a: prima di proseguire l’espansione va calcolata l’intera sequenza di ricatture.'),
  entry('kings-indian:smyslov',
    'Ae2 prepara l’arrocco, ma ...Cxg3 cambia il cavallo per l’alfiere. La ricattura con il pedone h aprirà la colonna h per il Bianco: la struttura e la scelta del lato d’arrocco dovranno essere valutate nella nuova posizione.',
    'Tc1 prepara la pressione dietro il pedone c4; il Nero arrocca corto. L’alfiere bianco in g3 è già stato cambiato: i piani devono ora coordinare i pezzi contro il centro e confrontare le linee disponibili con la sicurezza dei re.'),
  entry('kings-indian:semi-classical',
    'e4 guadagna spazio e controlla d5; ...c6 contesta quella casa. Il cambio precedente dei pedoni d ha lasciato una colonna d aperta: il Bianco può cercare attività con le torri, mentre il Nero prepara il controgioco centrale.',
    'b5 attacca c6; ...Cc5 attacca la donna a4 e il pedone e4. Il Nero risponde sul fianco con attività centrale: il Bianco deve affrontare questi bersagli prima di continuare ad avanzare i pedoni.'),
  entry('grunfeld:fianchetto',
    'Cc3 attacca d5; ...Cfd7 attacca il cavallo e5. Entrambi usano i pezzi contro i punti centrali: il Bianco deve decidere quali cambi mantengono spazio senza consentire al Nero di liberarsi con facilità.',
    'Tc1 usa la colonna c aperta; ...Ae8 sottrae l’alfiere all’attacco del cavallo e5. Il Nero prepara una diversa difesa del centro: il Bianco deve trovare ingressi concreti, perché una colonna aperta da sola non garantisce un’invasione.'),
  entry('grunfeld:brinckmann',
    'Axa6 prende un cavallo, ma ...Dxg2 attacca la torre h1 sulla diagonale g2-h1. Il Nero crea controgioco invece di ricatturare subito l’alfiere: il Bianco deve verificare la posizione delle donne e i possibili cambi forzati.',
    'Cd2 centralizza il cavallo; ...Ab7 attiva l’alfiere sulla diagonale verso h1. Le donne sono state cambiate, ma la torre bianca è ancora un bersaglio: semplificare non significa poter trascurare lo sviluppo.'),
  entry('grunfeld:stockholm',
    'Ad3 sviluppa verso g6; ...dxc4 cattura e attacca l’alfiere. Il Nero usa i cambi per mettere alla prova il centro bianco: la ricattura può migliorare l’alfiere, ma va confrontata con la pressione sulla grande diagonale.',
    'cxd4 ricostruisce il centro; ...Ae6 sviluppa contro a2. Il Bianco ha nuovamente due pedoni centrali affiancati, mentre il Nero cerca attività dei pezzi contro di essi: il centro forte deve essere sostenuto, non soltanto occupato.'),
  entry('nimzo:rubinstein',
    'bxc3 ottiene la coppia degli alfieri ma doppia i pedoni c; ...dxc4 attacca l’alfiere d3. Il Nero trasforma subito il centro: il Bianco deve sfruttare le diagonali degli alfieri prima che la struttura diventi soltanto un bersaglio.',
    'dxe5 e ...Cxe5 aprono la colonna d e centralizzano il cavallo nero, che attacca d3 e f3. I cambi devono essere calcolati nell’ordine corretto: l’attività degli alfieri bianchi dipende anche dalla sicurezza dei pezzi sotto attacco.'),
  entry('nimzo:samisch',
    'e4 occupa il centro; ...Ce8 riorganizza il cavallo e libera il pedone f. Il Bianco ha spazio e due alfieri, ma il Nero può preparare rotture contro la catena: sviluppo e difesa dei pedoni c restano parte dello stesso piano.',
    'cxd4 ricostruisce il centro; ...Ca5 attacca c4. Il Nero cerca un bersaglio nella struttura bianca invece di contendere subito tutte le case centrali: il Bianco deve capire se difenderlo, avanzarlo o usare il tempo per l’iniziativa.'),
  entry('nimzo:leningrad',
    'f3 sostiene e4; ...Cbd7 completa il sostegno a e5 e c5. Il Bianco prepara un centro ampio dietro i pedoni c doppiati: guadagnare spazio non elimina il bisogno di coordinare i pezzi e scegliere un rifugio per il re.',
    'Il Bianco arrocca lungo; ...Cg6 controlla e5 e f4. Il re bianco si trova dietro la struttura dei pedoni c: il piano sul lato di re deve lasciare tempo anche alla difesa delle linee sul lato di donna.'),
  entry('queens-indian:ba6',
    'Ce5 attacca f7 e c6; ...Cfd7 propone il cambio del cavallo avanzato. Il Nero cerca di ridurre lo spazio bianco senza indebolire i pedoni: la scelta delle ricatture decide quali pezzi resteranno attivi sulle grandi diagonali.',
    'd5 attacca e6 e libera d4; il Nero arrocca. L’alfiere bianco in c6 è attivo, ma va confrontato con le torri nere e i pedoni che possono aprire il centro: conservare un pezzo avanzato richiede sostegni concreti.'),
  entry('queens-indian:e3',
    'exd4 ricattura con il pedone e; ...d5 stabilisce una nuova tensione contro c4. I due alfieri in fianchetto possono cambiare valore quando il centro si apre: prima di fissare la struttura occorre guardare le diagonali.',
    'Ad3 riporta l’alfiere verso il centro; ...Tc8 usa la colonna c semiaperta. Il Nero prepara pressione lungo una linea concreta: il Bianco deve coordinare torri e alfieri prima di risolvere la tensione fra c4 e d5.'),
  entry('queens-indian:kasparov',
    'Dc2 attacca il cavallo e4, ma ...Axc3+ introduce uno scacco prima di risolvere quel confronto. La ricattura cambierà i pedoni del lato di donna: una minaccia a un pezzo non esclude una risposta intermedia forzante.',
    'Axe4 elimina il cavallo; ...fxe4 porta un pedone nero in e4 e attacca f3. Il Nero rende semiaperta la colonna f e cambia il centro: il Bianco deve calcolare la risposta della donna prima di continuare l’attacco ai pedoni neri.'),
  entry('catalan:closed',
    'e4 attacca d5 e guadagna spazio; ...Ab7 completa il fianchetto nero. Gli alfieri possono trovarsi su diagonali lunghe ma bloccate: il momento dei cambi centrali decide quali linee diventano davvero utilizzabili.',
    'Ch4 prepara un ingresso in f5; ...cxd4 cattura al centro. Il Nero rende semiaperta la colonna c per la propria torre, mentre il Bianco cerca attività dei cavalli: il piano sul lato di re deve includere la risposta alla tensione centrale.'),
  entry('catalan:check',
    'Td1 prepara pressione sulla colonna d; ...b6 sostiene c5 e apre lo sviluppo dell’alfiere c8. Lo scacco iniziale in b4 ha modificato l’ordine di sviluppo bianco, ma la scelta dei cambi centrali resta il problema principale.',
    'Cb5 entra nel campo nero; ...Axb5 cambia l’alfiere per il cavallo. Dopo la ricattura del pedone c cambieranno la colonna c e il controllo del centro: il guadagno della coppia degli alfieri va confrontato con questa trasformazione.'),
  entry('catalan:early-c5',
    'Entrambi i re arroccano dopo i cambi centrali. Il Nero ha un pedone isolato in d5 e pezzi già attivi: il Bianco può cercare un blocco, ma deve evitare che i tempi spesi contro il pedone permettano un’iniziativa avversaria.',
    'hxg4 elimina l’alfiere; ...Ce6 riorganizza il cavallo con controllo di d4 e f4. Il Nero ha lasciato cambiare il proprio alfiere per mantenere un cavallo attivo: dopo ogni ricattura bisogna ricontrollare le case centrali, anziché considerare conclusa la sequenza.'),
  entry('dutch:classical',
    'b4 guadagna spazio sul lato di donna; il Nero arrocca. I pedoni f5 ed e5 danno al Nero presenza centrale: il Bianco deve preparare le rotture con i pezzi, senza spingere automaticamente contro il re.',
    'Cd2 riorganizza il cavallo con controllo di e4 e c4; ...Cd7 sostiene e5 e c5. Le manovre preparano il momento delle spinte centrali: prima di cambiare i pedoni occorre capire quali pezzi troveranno case migliori.'),
  entry('dutch:leningrad',
    'dxe5 e ...dxe5 aprono la colonna d. Il Nero conserva i pedoni e5 e f5, ma consente il cambio delle donne: il Bianco può ridurre le minacce al re mentre prepara pressione sulla struttura centrale.',
    'Tb1 prepara attività sulla colonna b; ...Cfd7 riorganizza il cavallo verso le case centrali. Dopo i cambi delle donne e dei pedoni f, la colonna g semiaperta per il Nero e le maggioranze di pedoni guidano nuovi piani.'),
  entry('dutch:staunton',
    'c3 sostiene d4; ...Ab7 completa il fianchetto sul lato di donna. Il pedone sacrificato è già stato recuperato, ma il Nero ha due alfieri: il Bianco deve trasformare il centro e i tempi di sviluppo in attività concreta.',
    'a3 controlla b4; ...g6 controlla f5 e modifica la copertura del re nero. Le torri sulla colonna e e gli alfieri attivi richiedono attenzione alle catture e agli scacchi intermedi, prima di iniziare altre spinte di pedone.'),
  entry('dutch:hopton',
    'Ah4 attacca il cavallo f6; ...a6 controlla b5. Il Nero ha spinto i pedoni g e h per inseguire l’alfiere: il Bianco deve confrontare le case indebolite con lo spazio avversario, mantenendo il proprio re pronto ai cambi centrali.',
    'e4 attacca f5; ...Cc6 aggiunge sostegno a e5 e controllo di d4. Le donne sono state cambiate, ma il centro resta dinamico: l’attività dei cavalli e le colonne aperte contano più di un attacco di pedoni ormai privo delle donne.'),
  entry('benoni:modern',
    'Ae2 prepara l’arrocco; ...Te8 attacca e4 lungo la colonna e semiaperta. Il Nero sfrutta le linee lasciate dal cambio dei pedoni centrali: la maggioranza bianca al centro deve essere sostenuta prima di avanzare ancora.',
    'Af4 risponde all’attacco del pedone f6, ma ...fxe5 cattura al centro e attacca di nuovo l’alfiere. Il Nero guadagna tempi attraverso le rotture: il Bianco deve confrontare il proprio spazio con l’attività che concede ai pezzi avversari.'),
  entry('benoni:benko-accepted',
    'g3 prepara un rifugio in g2 per il re, che ha perso l’arrocco; ...Ag7 completa il fianchetto nero. Il pedone in più ha un costo in tempi: il Bianco deve coordinarsi mentre il Nero prepara pressione sulle colonne a e b.',
    'Ad2 completa lo sviluppo dell’alfiere; ...Cb6 attacca d5. La compensazione nera non dipende soltanto dalle colonne del lato di donna: un bersaglio centrale può distogliere i pezzi bianchi dalla difesa dei pedoni sul fianco.'),
  entry('benoni:czech',
    'a4 limita una futura ...b5; ...b6 sostiene c5 e prepara il lato di donna. Il centro è bloccato: i tempi di manovra vanno usati per preparare le rotture, senza presumere che la posizione resterà chiusa per tutta la partita.',
    'b3 sostiene c4, ma ...b5 attacca sia a4 sia c4. Il Nero ha preparato la rottura sul fianco: prima di cercare gioco sul lato di re, il Bianco deve scegliere quali cambi mantengono un centro e un re sicuri.'),
  entry('benoni:old',
    'a4 controlla b5; ...e6 attacca d5. Il Nero prepara l’apertura del centro dopo aver completato l’arrocco: il Bianco deve decidere se conservare la catena avanzata oppure cambiarla per sfruttare le linee aperte.',
    'exd5 attacca l’alfiere e6; ...Tad8 attacca a sua volta il pedone d5. Quel pedone copre la donna d1: prima di catturare l’alfiere bisogna includere ...Txd1 nel calcolo, verificando anche gli scacchi intermedi disponibili al Bianco.'),
  entry('budapest:adler',
    'b4 attacca l’alfiere c5, che si ritira in e7. Il Nero ha già recuperato il pedone del gambetto: il vantaggio di spazio bianco va trasformato in sviluppo, senza continuare a difendere un pedone in più che non esiste più.',
    'f4 attacca il cavallo e5; ...Cg6 lo conserva e attacca f4. Il Bianco ha pedoni doppiati sulla colonna f dopo il cambio in f3: l’avanzata crea spazio ma anche punti da sostenere prima di aprire altre linee.'),
  entry('budapest:alekhine',
    'Txg1 riprende l’alfiere; ...Dxh2 prende un pedone e attacca la torre g1. Il re bianco in d2 rende gli scacchi particolarmente importanti: recuperare materiale non basta se la donna avversaria può continuare a guadagnare tempi.',
    'Rd1 riorganizza il re; ...Ce6 centralizza il cavallo. Il Bianco deve trovare coordinazione dopo le mosse forzate iniziali: l’esposizione del re e i pezzi ancora da sviluppare pesano quanto il bilancio materiale del gambetto.'),
  entry('budapest:rubinstein',
    'Ae2 prepara l’arrocco; ...d6 sostiene il cavallo e5 e libera l’alfiere c8. Il Nero ha recuperato il pedone e cerca uno sviluppo fluido: il Bianco deve usare lo spazio e la coppia degli alfieri senza concedere iniziativa.',
    'Tfe1 coordina le torri sul centro; ...a5 controlla b4. Il Nero prepara spazio sul lato di donna, mentre il Bianco deve stabilire quando avanzare e4: una spinta centrale cambia anche il lavoro degli alfieri.'),
  entry('english:four-knights',
    'f4 attacca il cavallo e5; ...Cg6 risponde attaccando f4 e l’alfiere h4. Il Nero trasforma una ritirata in una doppia pressione: prima di continuare l’espansione il Bianco deve verificare quali pezzi e pedoni restano protetti.',
    'Tb1 preme su b7; ...Te8 mette pressione a e2 lungo la colonna e semiaperta. I due lati cercano attività su colonne diverse: la cattura di un pedone sul fianco va confrontata con l’apertura di linee verso il proprio re.'),
  entry('english:reversed-sicilian',
    'a3 prepara b4; ...h6 controlla g5. Il Bianco organizza l’espansione sul lato di donna dietro il fianchetto: il tempo in più della Siciliana a colori invertiti aiuta la preparazione, ma non sostituisce il controllo delle risposte centrali.',
    'b5 guadagna spazio, ma ...Dd7 attacca il pedone lungo la diagonale d7-c6-b5. Il Nero collega i pezzi prima di aprire il centro: il Bianco deve sostenere l’espansione o usarla per ottenere linee utili alle torri.'),
  entry('english:botvinnik',
    'b3 sostiene c4; ...f5 attacca e4. Il centro con c4 ed e4 lascia una casa in d4: quando il Nero rompe sul lato di re, il Bianco deve valutare se i cambi conservano il controllo delle case centrali.',
    'Dd2 coordina i pezzi; ...Cd4 attacca il cavallo e2 e i pedoni b3 e f3. Il punto debole d4 diventa un ingresso concreto: prima di continuare un piano sul fianco occorre decidere come affrontare il cavallo avanzato.'),
  entry('english:anglo-indian',
    'Ag5 attacca la donna f6; ...Df5 mantiene il controllo centrale. I cambi iniziali hanno già eliminato un cavallo per parte e modificato i pedoni c: lo sviluppo deve seguire la posizione concreta, non un impianto standard dell’Inglese.',
    'Tb1 attacca il cavallo b4; ...Cc2+ risponde con scacco e controlla d4. Una minaccia al pezzo può consentire una risposta più forzante: il Bianco deve calcolare gli scacchi intermedi prima di considerare guadagnato un tempo.'),
  entry('reti:accepted',
    'Ae2 ritira l’alfiere; ...Re7 centralizza il re dopo il cambio delle donne. Il gambetto iniziale è stato recuperato: senza donne la sicurezza del re si valuta diversamente, ma lo sviluppo degli altri pezzi resta necessario.',
    'Af3 attacca b7; ...Tab8 difende il pedone con la torre. Il Nero non deve rispondere sempre avanzando i pedoni: coordinare una difesa può anche preparare attività sulla colonna, mentre il Bianco cerca nuovi bersagli.'),
  entry('reti:kings-indian-attack',
    'De2 sostiene e4; ...h6 controlla g5. Il Bianco prepara e5 dietro i pezzi, mentre il Nero ha già spazio sul lato di donna: l’attacco Est-Indiano richiede il momento giusto per avanzare, non soltanto uno schema di sviluppo.',
    'Cb3 attacca c5, ma ...fxe5 cattura la punta del centro bianco. Il Nero apre linee prima che l’attacco al re prenda forza: le ricatture e i cambi dei cavalli decideranno quali pezzi possono partecipare al seguito.'),
  entry('reti:symmetrical',
    'Af4 e ...Af5 sviluppano entrambi gli alfieri fuori dalle catene di pedoni. La simmetria non elimina le differenze: una rottura o un cambio al centro può dare valore diverso alle stesse case per i due colori.',
    'Taxd1 conclude il cambio delle donne; ...Tab8 attacca l’alfiere b7. La cattura del pedone ha attivato una torre nera: il Bianco deve far rientrare l’alfiere senza perdere di vista il controllo della colonna d aperta.'),
  entry('reti:new-york',
    'Il Bianco arrocca; ...Ag4 attacca il cavallo f3. I tempi spesi per inseguire l’alfiere con Ch4 non hanno impedito il suo ritorno in gioco: ora conta completare il centro e coordinare i pezzi, anziché ripetere l’inseguimento.',
    'Cc3 attacca il cavallo e4 e il pedone d5; ...e6 sostiene d5 e f5. Il Nero rinforza il centro, ma consente cambi che possono trasformarlo: il Bianco deve confrontare l’attività del cavallo avanzato con le nuove linee degli alfieri.'),
  entry('four-knights:rubinstein',
    'Ca4 attacca l’alfiere c5, che si ritira in b6. Il Bianco può scegliere di cambiarlo, ma deve confrontare il tempo speso sul bordo con lo sviluppo dei pezzi e con la nuova struttura che nascerà dalla ricattura.',
    'f4 attacca e5; ...f5 attacca e4. I due lati rompono quasi simultaneamente la simmetria centrale: prima di catturare bisogna vedere quali colonne si aprono verso i re e quali pezzi sostengono i pedoni.'),
  entry('four-knights:italian',
    'Cce2 riorganizza il cavallo dopo l’espansione centrale nera; ...Ad6 punta a h2. Il re nero ha perso l’arrocco, ma il Nero ha tempi di sviluppo: il Bianco deve coordinare i cavalli prima di cercare un attacco.',
    'd4 permette ...exd3 en passant: il pedone nero lascia e4, cattura quello arrivato in d4 e raggiunge d3. Questa possibilità dura un solo turno e cambia il centro; prima di avanzare due case bisogna includerla nel calcolo.'),
  entry('four-knights:glek',
    'Axf6 elimina il cavallo; ...Dxf6 attiva la donna e attacca il cavallo f3. Il Bianco cede uno dei propri alfieri per modificare i difensori centrali: il vantaggio delle case va confrontato con l’attività che ottiene la donna avversaria.',
    'Ce3 ritira il cavallo dalla pressione di c6; ...h5 prepara spazio sul lato di re. L’alfiere g2 è ancora bloccato dal centro: per renderlo utile il Bianco deve scegliere quando cambiare i pedoni o aprire una diagonale.'),
  entry('four-knights:belgrade',
    'Dh5+ impone una risposta; ...g6 interrompe lo scacco e attacca la donna. Il Bianco usa le mosse forzanti per compensare i tempi investiti nel gambetto, ma deve mantenere collegati i cavalli e la sicurezza del re.',
    'Rd1 sposta il re senza arroccare; ...h6 attacca il cavallo g5. Il centro è stato trasformato da più cambi: prima di recuperare materiale il Bianco deve risolvere le minacce ai pezzi e verificare le linee delle donne.'),
  entry('larsen:indian',
    'Cxc5 prende un pedone e attacca l’alfiere e6; ...dxe3 cattura al centro e attacca d2 e f2. Il Nero evita una risposta passiva: prima di conservare il pedone in più il Bianco deve valutare le ricatture e la sicurezza del re.',
    'exd5 elimina l’alfiere d5, ma ...Dxc5 riprende il cavallo e attacca d5. La sequenza scambia pezzi su case diverse: contare soltanto la prima cattura nasconderebbe sia il materiale restituito sia i nuovi bersagli della donna.'),
  entry('larsen:sicilian',
    'g3 prepara il fianchetto di re; ...h5 guadagna spazio sul fianco. Il Nero può attaccare la copertura del futuro arrocco mentre il centro è chiuso: il Bianco deve scegliere tempi di sviluppo che permettano di rispondere alle spinte.',
    'hxg3 riprende il pedone e apre la colonna h per entrambi; ...Ae6 attacca il cavallo d5. L’apertura del fianco non autorizza a ignorare il centro: il pezzo avanzato va sostenuto o cambiato considerando le linee delle torri.'),
  entry('larsen:symmetrical',
    'Il Bianco arrocca; ...Ce8 riorganizza il cavallo e libera il pedone f. I due fianchetti sul lato di donna non rendono simmetrici i piani: il Bianco ha già avanzato e4 e f4, mentre il Nero può preparare rotture contro quella catena.',
    'Ce2 attacca il cavallo d4; ...Db6 coordina donna e pedone c5. Il cavallo nero centrale limita i pezzi bianchi: prima di cambiarlo occorre valutare la ricattura e le diagonali che si aprirebbero verso i re.'),
  entry('larsen:dutch',
    'f3 attacca l’alfiere g4; ...Af5 lo conserva e attacca il pedone g6. Il Bianco ha conquistato materiale sul lato di re, ma deve completare lo sviluppo mentre il Nero prepara il recupero dei pedoni e l’attività degli alfieri.',
    'Rb1 e ...Rb8 allontanano i re dalla colonna c dopo l’arrocco lungo. I tempi dedicati alla sicurezza preparano il gioco delle torri: l’iniziativa dipenderà dalle rotture centrali e dalle diagonali, non dal solo pedone b3 iniziale.'),
  entry('bird:symmetrical',
    'Ae3 sviluppa con controllo centrale; ...Th8 ritira la torre dopo aver preso quella in h1. La colonna h aperta e i re ancora al centro rendono il bilancio materiale insufficiente: il Bianco deve trovare tempi per coordinare i pezzi.',
    'Aa6 attacca b7; ...e6 attacca la donna d5. Il Nero risponde a un bersaglio sul fianco con una minaccia alla donna: prima di catturare occorre calcolare quale attacco ha priorità e quali scacchi restano disponibili.'),
  entry('bird:indian',
    'De1 sostiene e4; ...b6 sostiene c5 e prepara il lato di donna. Il Bianco può costruire un attacco sul lato di re con i pedoni e ed f, ma il Nero dispone di spazio sul fianco opposto e di rotture da preparare.',
    'g4 controlla f5; ...Cd7 riorganizza il cavallo verso e5 e c5. Il Bianco prepara nuove spinte davanti al proprio re: prima di aprire linee deve confrontarne la rapidità con il controgioco nero sulla colonna a e sulle case centrali.'),
  entry('bird:sicilian',
    'c3 attacca il cavallo d4, che raggiunge b5 e attacca lo stesso pedone c3. Un inseguimento non elimina l’attività del pezzo avversario: il Bianco deve sostenere il centro mentre prepara l’attacco sul lato di re.',
    'Cf2 riorganizza il cavallo e sostiene e4; ...b6 prepara l’alfiere c8 e controlla c5. Il Nero ha già giocato ...f6 contro il cavallo e5: una nuova spinta centrale va valutata insieme alle ricatture e alle diagonali che libererebbe.'),
  entry('bird:fianchetto',
    'dxe4 ricattura al centro; ...e5 attacca f4 e controlla d4. Il Nero sfida la catena che sostiene il progetto offensivo bianco: prima di aggiungere un altro pezzo all’attacco occorre stabilizzare o cambiare il centro.',
    'gxf4 ricattura e rende semiaperta la colonna g per il Bianco; ...Ch6 conserva il cavallo con controllo di f5. La copertura del re bianco è cambiata: le nuove linee possono aiutare l’attacco, ma vanno considerate anche dalla parte del difensore.'),
  entry('trompowsky:d5',
    'Il Bianco arrocca; ...Cf6 centralizza il cavallo. Il Nero ha due pedoni sulla colonna f, ma anche la coppia degli alfieri: l’imperfezione strutturale non elimina il bisogno del Bianco di creare bersagli e coordinare i pezzi.',
    'Te1 coordina la torre con il centro; ...g6 sostiene f5. Il Nero consolida la struttura dopo aver avanzato uno dei pedoni f: il Bianco deve distinguere le debolezze effettivamente attaccabili da quelle che restano ben difese.'),
  entry('trompowsky:c5',
    'Cf4 sostiene d5; ...e6 attacca quel pedone e sostiene f5. Il Nero ha già doppiato i pedoni f con ...gxf6, ma può aprire il centro: il Bianco deve preparare le ricatture prima di giudicare favorevole la struttura.',
    'exf4 riprende l’alfiere; ...exd5 apre la colonna e e attacca l’alfiere c4. I cambi modificano entrambi i centri: il Bianco deve mettere al sicuro il pezzo attaccato senza perdere il controllo delle linee aperte.'),
  entry('trompowsky:e6',
    'd5 attacca c6 ed e6; ...Ce5 centralizza il cavallo. Il Bianco guadagna spazio con il re già arroccato lungo, ma il Nero conserva una casa attiva: il seguito deve considerare i cambi dei pezzi prima di aprire altri fronti.',
    'hxg5 e ...hxg5 aprono la colonna h per entrambi. Il cambio delle torri può diventare concreto, ma la donna nera in f6 partecipa alla difesa: l’apertura di una colonna va valutata insieme ai pezzi che possono usarla.'),
  entry('trompowsky:raptor',
    'exd6 e ...Dxd6 eliminano i pedoni centrali avanzati e attivano la donna nera contro d5. Il cambio iniziale dell’alfiere per il cavallo ha reso semiaperta la colonna h per il Bianco: la torre può cercare attività se il centro resta sotto controllo.',
    'Txd1 conclude il cambio delle donne; ...Cxe7 recupera il cavallo avanzato. La posizione richiede nuovi piani: la torre bianca attiva e i pedoni devono essere coordinati per il mediogioco, anziché continuare un attacco di donna ormai terminato.'),
  entry('colle:torre-indian',
    'e5 attacca il cavallo f6; ...Ce4 risponde attaccando l’alfiere g5 e guardando d2 e f2. Il Nero trasforma una ritirata obbligata in attività centrale: prima di inseguire ancora il cavallo il Bianco deve confrontare i bersagli.',
    'Il Bianco arrocca; ...f5 sostiene il cavallo e4. La presa en passant precedente ha già modificato il centro e la colonna e: il Bianco deve rivedere il piano dei pezzi, senza assumere che la struttura iniziale del Torre sia rimasta intatta.'),
  entry('colle:stonewall',
    'Ac2 si sottrae al pedone c4; ...Ce7 riorganizza il cavallo verso d5 e f5. La struttura Stonewall dà controllo di e5, ma l’alfiere bianco ha meno spazio: scegliere la rottura richiede di coordinare anche i pezzi rimasti indietro.',
    'Cxg4 e ...hxg4 cambiano il cavallo avanzato per l’alfiere e rendono semiaperta la colonna h per il Nero. Il Bianco deve confrontare la riduzione della pressione sui pezzi con le nuove linee vicino al proprio re.'),
  entry('colle:koltanowski',
    'a4 limita ...b5; ...cxd4 cambia il centro. La ricattura del pedone e lascerà d4 isolato: il Bianco può ottenere attività dei pezzi, ma deve preparare sostegni e rotture invece di difendere quel pedone in modo passivo.',
    'a5 attacca il cavallo b6, che raggiunge d5 e attacca c3. Il Nero occupa la casa davanti al pedone isolato: il Bianco deve valutare se cambiarlo o creare attività prima che il blocco renda più difficile la spinta d5.'),
  entry('colle:torre-classical',
    'Te1 prepara il gioco sulla colonna e; ...Ab7 sviluppa lungo la grande diagonale. La futura spinta e4 richiede preparazione: il Bianco deve contare i controlli centrali, mentre il Nero cerca attività con l’alfiere e i cavalli.',
    'Dxd2 riprende il cavallo; ...e5 attacca sia d4 sia l’alfiere f4. Il Nero ha preparato una rottura con tempo su un pezzo: prima di riprendere il proprio piano il Bianco deve calcolare i cambi centrali.'),
  entry('bogo:qe7',
    'e4 e ...e5 stabiliscono una tensione centrale. Il Nero ha cambiato l’alfiere dello scacco iniziale per quello bianco: ora il valore dei cavalli dipenderà dalle case che restano disponibili dopo un’eventuale avanzata d5.',
    'cxd6 e ...cxd6 aprono la colonna c e spostano un pedone nero in d6. Il Bianco può cercare pressione sulla nuova struttura, ma deve considerare anche le case e5 e c5 sostenute dalla ricattura.'),
  entry('bogo:be7',
    'Af4 attacca il cavallo b8 lungo la diagonale; ...Cbd7 lo sviluppa e controlla e5 e c5. Il Nero ha ritirato l’alfiere dello scacco iniziale: il Bianco deve usare i tempi di sviluppo ottenuti per coordinare il centro.',
    'Cc3 sviluppa contro d5; ...Cb8 ritira il cavallo. Il Bianco guadagna libertà, ma deve stabilire se il cambio in b8 migliora davvero la posizione: eliminare un pezzo passivo può anche attivare la donna avversaria.'),
  entry('bogo:a5',
    'Cc3 sviluppa, ma ...Ce4 attacca la donna d2 e il cavallo c3. Il Nero usa il centro per guadagnare tempi: una doppia pressione va affrontata confrontando i cambi disponibili, prima di completare altre mosse di sviluppo.',
    'Tac1 sostiene c4; ...Cc6 attacca d4 e controlla e5. Il Nero completa lo sviluppo contro il centro bianco: le torri attive devono essere collegate a una rottura o a un bersaglio, senza lasciare i pedoni centrali indifesi.'),
  entry('bogo:nc6',
    'Il Bianco arrocca lungo; ...De7 coordina il centro nero. Il cambio iniziale dell’alfiere per il cavallo ha già alterato l’equilibrio dei pezzi: il lato d’arrocco richiede ora attenzione alle spinte nere sul lato di donna.',
    'Axb5 cattura e attacca il cavallo c6, che va in a5. Il Nero conserva attività sul fianco del re bianco: un pedone conquistato deve essere confrontato con le linee che le torri e i cavalli potranno usare contro l’arrocco.'),
  entry('old-indian:janowski',
    'Entrambi i re arroccano dopo il cambio in d5. L’alfiere nero è già fuori dalla catena, in f5: il Bianco deve preparare pressione centrale tenendo conto di quel pezzo attivo, senza applicare un piano contro un alfiere chiuso in c8.',
    'Cdb5 attacca d6 e a7; ...Ae6 sviluppa verso a2. Il Nero crea attività per non limitarsi alla difesa dei pedoni: il Bianco deve valutare se conservare il cavallo avanzato aiuta il centro o lo allontana dai suoi sostegni.'),
  entry('old-indian:fianchetto',
    'Da4+ si sottrae all’attacco del cavallo a5 e dà scacco; ...c6 interrompe la diagonale. Il Bianco ha guadagnato un tempo sulla posizione del re, ma la donna resta un possibile bersaglio mentre i pezzi devono ancora svilupparsi.',
    'd5 attacca c6; ...e3 attacca f2 e mantiene un pedone nel campo bianco. Il Nero non si limita a difendere il proprio centro: il Bianco deve affrontare la minaccia interna prima di cercare altro spazio sul lato di donna.'),
  entry('old-indian:ukrainian',
    'De2 centralizza la donna; ...a5 controlla b4. Il Bianco ha ottenuto la coppia degli alfieri dopo il cambio in f3, ma ha già impegnato i pedoni g e h: lo sviluppo deve accompagnare l’attacco prima che il centro si apra.',
    'Ad2 completa lo sviluppo; ...e5 attacca d4. La colonna h è stata aperta dai cambi precedenti, ma il Nero risponde al centro: il Bianco deve calcolare le ricatture e scegliere la sicurezza del re prima di usare le torri sul fianco.'),
  entry('old-indian:classical-e4',
    'Af1 conserva l’alfiere dietro il centro; ...b5 attacca c4. Il Nero prepara controgioco sul lato di donna: il Bianco deve valutare i cambi sul fianco insieme alla tensione fra d4 ed e5.',
    'f4 attacca il cavallo e5, che raggiunge g6 e attacca f4. Il Bianco cerca spazio sul lato di re, ma il pedone appena avanzato diventa un bersaglio: preparare l’attacco richiede sostegni e attenzione alle case centrali.'),
  entry('nimzowitsch:e5',
    'Rd1 risponde allo scacco della donna h4; ...dxe4 apre la colonna d. Il Nero cerca linee verso un re che ha perso l’arrocco: prima di prendere il cavallo g6 il Bianco deve includere nel calcolo gli scacchi degli alfieri e delle torri.',
    'Rc1 allontana il re dalla colonna d; ...Cf6 sviluppa con controllo di e4 e d5. Il Bianco ha raccolto materiale sul lato di re, ma deve ancora coordinare i pezzi per resistere all’attività delle torri nere.'),
  entry('nimzowitsch:scandinavian',
    'Ad3 sviluppa verso h7; ...Ag4 attacca il cavallo f3. Il Nero ha offerto un pedone per tempi di sviluppo: il Bianco deve completare la sicurezza del re senza consentire che la pressione sul cavallo disgreghi il centro.',
    'h3 attacca l’alfiere g4, che si ritira in h5. Il Bianco conserva il pedone in più, ma deve trasformarlo in un vantaggio utilizzabile: sviluppo delle torri e controllo del centro hanno priorità rispetto a inseguire ancora l’alfiere.'),
  entry('nimzowitsch:two-knights',
    'Ab5 attacca il cavallo c6; ...a6 attacca a sua volta l’alfiere. Il centro è stato modificato dal sacrificio e6: prima di cambiare i pezzi bisogna verificare le ricatture e le diagonali che si apriranno verso i re.',
    'Cg5 attacca e6 e l’alfiere h6; ...Ag7 conserva l’alfiere e punta verso d4. Il Bianco ha aperto la colonna h con i cambi di pedone: la scelta fra cambiare torri e mantenere la pressione dipende anche dalla difesa del centro.'),
  entry('nimzowitsch:advance',
    'Ae2 prepara l’arrocco; ...Ch6 sviluppa con controllo di f5. La rottura ...f6 ha già cambiato il centro bianco: il pedone e5 richiede sostegni, mentre il Nero cerca attività contro la struttura avanzata.',
    'Cxf5 e ...exf5 cambiano il cavallo per l’alfiere e doppiano i pedoni neri sulla colonna f. La colonna e si libera e le donne possono diventare più attive: il Bianco deve confrontare la struttura ottenuta con i tempi necessari alla sicurezza del re.'),
  entry('owen:classical',
    'Dh4 attacca il cavallo f6; ...Axh1 prende la torre. Il Nero investe tempi della donna e dell’alfiere per raccogliere materiale, mentre il Bianco cerca minacce al re che ha perso l’arrocco: le mosse forzanti devono guidare il calcolo.',
    'Dg3+ costringe il re a tornare in f8. Il Bianco ha perso una torre, ma continua a guadagnare tempi con gli scacchi: deve completare lo sviluppo e trovare minacce concrete, senza considerare l’esposizione del re una compensazione automatica.'),
  entry('owen:knight',
    'Ag5 attacca il cavallo f6; il Nero arrocca. La cattura iniziale in e4 ha dato al Nero un pedone, ma tempi al Bianco per costruire il centro: il valore di d5 dipende dalla capacità dei pezzi di sostenerlo.',
    'Tfe1 mette pressione a e6; ...e5 avanza il pedone e chiude parte delle diagonali. Il Nero modifica il centro invece di limitarsi a difenderlo: il Bianco deve preparare una rottura o un cambio che renda utili le torri.'),
  entry('owen:english-e4',
    'g3 interrompe lo scacco della donna h4 e la attacca; ...Dh5 conserva pressione su f3. Il Nero usa la donna per guadagnare tempi contro i pedoni avanzati: il Bianco deve completare lo sviluppo mentre difende i bersagli creati.',
    'hxg3 riprende il cavallo; ...Df6 attacca d4 e f3. Il Nero ha ceduto un cavallo per l’alfiere e modificato la copertura del re bianco: il seguito richiede di coordinare i pezzi attorno ai due pedoni attaccati.'),
  entry('owen:guatemala',
    'Cc3 sviluppa con controllo di d5 ed e4; ...b5 attacca c4. Il cambio iniziale dell’alfiere in a6 ha lasciato al Nero un cavallo poi rientrato in c7: il Bianco deve confrontare spazio centrale e controgioco sul lato di donna.',
    'Ag5 attacca il cavallo f6; ...Ce6 attacca l’alfiere g5 e il pedone d4. Il Nero crea una doppia pressione senza ritirare il pezzo attaccato: il Bianco deve calcolare i cambi e non trattare ogni minaccia come una ritirata obbligata.'),
  entry('open-games:danish',
    'Cxc3 riprende l’alfiere, ma ...dxc4 cattura anche quello in c4. Il Nero restituisce parte del materiale per ridurre i pezzi d’attacco: il Bianco deve giudicare la posizione dopo tutti i cambi, non soltanto dalle diagonali iniziali del gambetto.',
    'Td1 attacca la donna d8 lungo la colonna aperta; ...Dg5 risponde puntando a g2. Il Bianco guadagna un tempo utile con la torre, ma deve verificare gli scacchi e la sicurezza del re prima di continuare l’iniziativa.'),
  entry('open-games:ponziani',
    'Cxf6+ e ...Axf6 cambiano i cavalli con scacco e attivano l’alfiere nero. Il Bianco ha spazio grazie al pedone d5, ma deve sostenere la catena mentre completa lo sviluppo del lato di donna.',
    'Ce4 attacca d6; ...Cf6 attacca sia il cavallo e4 sia d5. Il Nero risponde al bersaglio strutturale con attività dei pezzi: il Bianco deve calcolare quali cambi conservano lo spazio e quali lo trasformano in pedoni deboli.'),
  entry('open-games:latvian',
    'Re2 risponde allo scacco della donna h1; ...c6 controlla d5 e prepara il centro. Entrambi i re hanno perso l’arrocco e sono esposti: il materiale conquistato sulle torri va confrontato con lo sviluppo e con gli scacchi disponibili.',
    'Axc8 elimina l’alfiere; ...Cf6 sviluppa attaccando la donna h5. Il Nero cerca tempi per completare il gioco dei pezzi: il Bianco deve conservare l’iniziativa controllando le mosse forzanti, senza affidarsi al solo vantaggio materiale.'),
  entry('open-games:elephant',
    'Af4 sviluppa verso il centro; ...Cb6 attacca l’alfiere c4. Il Nero ha già perso l’arrocco, ma usa i cavalli per guadagnare tempi: il Bianco deve coordinare l’attacco senza lasciare gli alfieri esposti alle minacce.',
    'Cd2 centralizza il cavallo; ...g5 attacca l’alfiere f4. Il Nero crea spazio davanti al proprio re in e7: il Bianco deve confrontare le case indebolite con la necessità immediata di conservare o cambiare il pezzo attaccato.'),
  entry('queens-pawn:blackmar-diemer',
    'Il Bianco arrocca lungo e attiva la torre sulla colonna d aperta; ...Cc6 sviluppa contro d4 ed e5. Il gambetto ha dato tempi di sviluppo, ma il Nero conserva materiale in più: il Bianco deve creare bersagli concreti prima che la difesa si coordini.',
    'Td2 si sottrae alla pressione dell’alfiere g4; il Nero arrocca lungo. I re sono sullo stesso lato e le donne restano attive: la pressione sulla colonna d deve essere sostenuta dai pezzi, senza dare per scontato un attacco al re.'),
  entry('queens-pawn:veresov',
    'Cc4 si sottrae al pedone f6; ...c5 attacca d4. Il Nero ha avanzato pedoni su entrambi i lati del centro: il Bianco deve sfruttare i tempi per svilupparsi e verificare quali case restano disponibili ai pezzi.',
    'Axh5+ prende un pedone con scacco; ...Rg7 porta il re fuori dalla diagonale. Il Bianco può cercare attività contro il re esposto, ma ha ancora il proprio re in e1: completare lo sviluppo resta necessario per sostenere le minacce.'),
  entry('queens-pawn:richter',
    'Ca3 ritira il cavallo dall’attacco di ...a6; il Nero arrocca. L’escursione in b5 ha richiesto tempi senza creare una minaccia decisiva: il Bianco deve organizzare un nuovo percorso del cavallo verso il centro.',
    'Cce1 riorganizza il cavallo; ...c4 fissa il lato di donna e libera c5. Il centro più chiuso permette manovre, ma il Nero può guadagnare spazio con i pedoni: il Bianco deve trovare una rottura prima che i pezzi restino senza case utili.'),
  entry('queens-pawn:englund',
    'Ag2 completa il fianchetto; ...a6 controlla b5. Il Nero ha già arroccato lungo, mentre il Bianco ha portato presto la donna in b3: conservare il pedone in più richiede ora di completare la sicurezza del re.',
    'Tae1 attacca la donna e2; ...Db5 risponde attaccando la donna b3. Una minaccia alla donna non garantisce un tempo gratuito: il Bianco deve confrontare il cambio delle donne con l’attività delle torri e dei cavalli.'),
  entry('other:sokolsky',
    'd3 sostiene e4; ...a5 attacca il pedone b4. Il Nero mette alla prova il pedone avanzato della Polacca: il Bianco deve decidere se sostenerlo, avanzarlo o cambiarlo in modo da conservare diagonali utili all’alfiere b2.',
    'Cc3 sviluppa con controllo di d5 ed e4; ...Ae6 completa lo sviluppo dell’alfiere. Il cambio dei pedoni centrali ha aperto linee e portato un alfiere nero in h2: la scelta dell’arrocco deve tenere conto di questa attività.'),
  entry('other:grob',
    'Rf1 risponde allo scacco dell’alfiere g3 e rinuncia all’arrocco; il Nero arrocca corto. Le spinte iniziali dei pedoni g e h hanno creato spazio ma anche linee verso il re bianco: lo sviluppo dei pezzi è ora prioritario.',
    'f4 avanza il pedone sotto pressione; ...b4 attacca il cavallo c3 e il pedone a3. Il Nero apre un secondo fronte: prima di proseguire sul lato di re il Bianco deve scegliere una risposta che mantenga coordinato il centro.'),
  entry('other:sodium',
    'dxc5 prende un pedone; ...Te8 porta una torre sulla colonna e aperta. Il cambio iniziale del cavallo in a3 ha lasciato al Bianco pedoni doppiati sul lato di donna: il materiale centrale non deve far trascurare lo sviluppo e il re.',
    'Rg3 espone il re fuori dalla prima traversa; ...Dxc5 recupera il pedone e attacca a3 e c2. Il Bianco deve cercare un rifugio e coordinare i pezzi: raccogliere altri pedoni non risolve le minacce della donna avversaria.'),
  entry('other:dunst',
    'Axa3 riprende il pedone avanzato, ma ...Axa3 cambia l’alfiere e richiede un’altra ricattura. La torre bianca potrà diventare attiva sulla terza traversa, ma il re è ancora al centro: attività e sicurezza devono procedere insieme.',
    'fxe5 attacca il cavallo f6, che raggiunge e4 e guarda d2. Il Bianco ha modificato il centro per recuperare un pezzo, ma il Nero ottiene un avamposto: il seguito deve confrontare la pressione sul pedone d4 con le minacce al re.'),
])
